import React, { useState, useCallback } from 'react';
import { IconKey } from '@tabler/icons-react';
import toast from 'react-hot-toast';
import { supabase } from '../supabaseClient';
import { useCachedData } from '../dataCache';
import SEO from '../components/SEO';
import PageTitle from '../components/PageTitle';
import { useT } from '../i18n';

const MAPS = [
  { id: 1, name: '零号大坝', icon: '🏗️', color: '#20e870' },
  { id: 2, name: '长弓溪谷', icon: '🏔️', color: '#18a0d0' },
  { id: 3, name: '巴克什', icon: '🏜️', color: '#e0a030' },
  { id: 4, name: '航天基地', icon: '🚀', color: '#d050d0' },
  { id: 5, name: '潮汐监狱', icon: '⛓️', color: '#e06040' },
  { id: 6, name: 'AZ3', icon: '🛰️', color: '#40d0c0' },
];

function DailyPassword() {
  const { t } = useT();
  const [copied, setCopied] = useState('');

  // One request: newest rows first. Show today's rows if present, otherwise
  // the latest 10 (same result as the old today-then-fallback two queries).
  const fetchPasswords = useCallback(async () => {
    const today = new Date().toISOString().split('T')[0];
    const { data } = await supabase
      .from('daily_passwords')
      .select('*')
      .order('date', { ascending: false })
      .order('map_id', { ascending: true })
      .limit(20);
    const rows = data || [];
    const todays = rows.filter(r => String(r.date).slice(0, 10) === today);
    return todays.length ? todays : rows.slice(0, 10);
  }, []);
  const [data, loading] = useCachedData('daily_passwords', fetchPasswords);
  const passwords = data || [];
  const lastUpdate = passwords.length > 0 ? (passwords[0].updated_at || passwords[0].date) : '';

  function formatTime(ts) {
    if (!ts) return '';
    const d = new Date(ts);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
  }

  function copyPw(secret, name) {
    navigator.clipboard.writeText(secret).catch(() => {
      const ta = document.createElement('textarea');
      ta.value = secret; document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta);
    });
    setCopied(name);
    toast.success(t('{name} 密码已复制！', { name: t(name) }));
    setTimeout(() => setCopied(''), 1500);
  }

  // 把密码拆成单个数字显示
  function renderDigits(secret, color) {
    return (
      <div style={{ display: 'flex', gap: 8, justifyContent: 'center' }}>
        {secret.split('').map((digit, i) => (
          <div key={i} style={{
            width: 48, height: 58,
            background: 'var(--bg-secondary)',
            border: `2px solid ${color}40`,
            borderRadius: 10,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontFamily: "'Orbitron', monospace",
            fontSize: 30, fontWeight: 900,
            color: color,
            textShadow: `0 0 12px ${color}40`,
          }}>
            {digit}
          </div>
        ))}
      </div>
    );
  }

  if (loading) return <div className="loading"><div className="spinner"></div>{t('加载每日密码中...')}</div>;

  const latestDate = passwords.length > 0 ? passwords[0].date : '';
  const todayPw = passwords.filter(p => p.date === latestDate);
  const isToday = latestDate === new Date().toISOString().split('T')[0];

  return (
    <div>
      <SEO title={t('每日密码')} path="/daily" description={t('三角洲行动每日地图密码查询，零号大坝、长弓溪谷、巴克什、航天基地、潮汐监狱每日更新。')} />
      <PageTitle icon={IconKey}>{t('每日密码')}</PageTitle>
      <p style={{ color: 'var(--text-muted)', fontSize: 14, marginBottom: 24 }}>
        {t('更新时间：')}{formatTime(lastUpdate) || t('暂无数据')}
        {latestDate && !isToday && (
          <span style={{ color: 'var(--danger)', marginLeft: 8, fontSize: 12 }}>{t('（非今日数据）')}</span>
        )}
      </p>

      {todayPw.length === 0 ? (
        <div style={{ textAlign: 'center', padding: 60, color: 'var(--text-muted)' }}>
          <div style={{ fontSize: 56, marginBottom: 16 }}>🔑</div>
          <p style={{ fontSize: 18, marginBottom: 8 }}>{t('今日密码暂未更新')}</p>
          <p style={{ fontSize: 14 }}>{t('密码每天 00:00 自动更新，请稍后再来查看')}</p>
        </div>
      ) : (
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(230px, 1fr))',
          gap: 16,
        }}>
          {todayPw.map(pw => {
            const map = MAPS.find(m => m.name === pw.map_name) || { icon: '🗺️', color: '#20e870' };
            const isCopied = copied === pw.map_name;
            return (
              <div key={pw.id} onClick={() => copyPw(pw.secret, pw.map_name)}
                style={{
                  background: 'var(--bg-card)',
                  border: `1px solid ${isCopied ? map.color : 'var(--border)'}`,
                  '--hover-border': map.color, '--hover-glow': `${map.color}18`, borderRadius: 16, padding: '26px 20px',
                  cursor: 'pointer', transition: 'all 0.2s',
                  textAlign: 'center', position: 'relative', overflow: 'hidden',
                  transform: isCopied ? 'scale(1.02)' : 'scale(1)',
                }}
                className="hover-card hover-glow"
              >
                {/* 顶部渐变条 */}
                <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 3, background: `linear-gradient(90deg, ${map.color}, ${map.color}66)` }} />

                <div style={{ fontSize: 32, marginBottom: 8 }}>{map.icon}</div>
                <div style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', marginBottom: 16 }}>
                  {t(pw.map_name)}
                </div>

                {/* 每位数字单独显示 */}
                {renderDigits(pw.secret, map.color)}

                <div style={{
                  marginTop: 14, fontSize: 12,
                  color: isCopied ? map.color : 'var(--text-muted)',
                  transition: 'all 0.2s',
                }}>
                  {isCopied ? `✅ ${t('已复制')}` : t('点击复制密码')}
                </div>
              </div>
            );
          })}
        </div>
      )}

      <div style={{
        marginTop: 30, padding: 16, background: 'var(--bg-card)',
        border: '1px solid var(--border)', borderRadius: 10,
        fontSize: 14, color: 'var(--text-muted)', lineHeight: 1.8,
      }}>
        <strong style={{ color: 'var(--text-secondary)' }}>💡 {t('提示：')}</strong>
        {t('密码每天 00:00 自动更新。点击密码卡片可以快速复制。')}
      </div>
    </div>
  );
}

export default DailyPassword;